public class Main {
    public static void main(String[] args) {
        int total = 0; //~ total starts at 0. The running sum will live here.
        for (int i = 1; i <= 3; i++) { //~ The loop checks: is i <= 3? If yes, run the body. After each round, i++ adds 1.
            total = total + i; //~ Add this round's i to the running total.
        } //~ End of the body. Back to the header for the next round.
        System.out.println(total); //~ i is now 4, so i <= 3 is false and the loop is over. Print the total.
    } //~ Done!
}

